package main

import (
	"fmt"
	"regexp"
	"strconv"
	"strings"
)

// Color stores either an ANSI color, a palette entry, or a true-color triple.
type Color struct {
	kind int
	n    int
	rgb  [3]int
}

func (c Color) escape(background bool) string {
	if c.kind == 0 {
		return ""
	}
	base := 30
	if background {
		base = 40
	}
	switch c.kind {
	case 1:
		return fmt.Sprintf("\x1b[%dm", base+c.n)
	case 2:
		return fmt.Sprintf("\x1b[%d;5;%dm", base+8, c.n)
	default:
		return fmt.Sprintf("\x1b[%d;2;%d;%d;%dm", base+8, c.rgb[0], c.rgb[1], c.rgb[2])
	}
}

var colorNames = []string{"black", "red", "green", "yellow", "blue", "magenta", "cyan", "white"}
var rgbPattern = regexp.MustCompile(`(?i)^rgb\(([0-9]+|0x[0-9a-f]+),[ \t]*([0-9]+|0x[0-9a-f]+),[ \t]*([0-9]+|0x[0-9a-f]+)\)$`)
var colorNumberPattern = regexp.MustCompile(`(?i)^(?:[0-9]+|0x[0-9a-f]+)$`)

func colorNumber(s string) (int, error) {
	base := 10
	if strings.HasPrefix(strings.ToLower(s), "0x") {
		base, s = 16, s[2:]
	}
	n, err := strconv.ParseUint(s, base, 8)
	return int(n), err
}

func parseColor(s string) (Color, error) {
	if s == "" || s == "default" {
		return Color{}, nil
	}
	for i, name := range colorNames {
		if s == name {
			return Color{kind: 1, n: i}, nil
		}
		if s == "light"+strings.ToUpper(name[:1])+name[1:] {
			return Color{kind: 1, n: 60 + i}, nil
		}
	}
	if len(s) == 7 && s[0] == '#' {
		n, err := strconv.ParseUint(s[1:], 16, 24)
		if err == nil {
			return Color{kind: 3, rgb: [3]int{int(n >> 16), int(n>>8) & 255, int(n) & 255}}, nil
		}
	}
	if m := rgbPattern.FindStringSubmatch(s); m != nil {
		var c Color
		c.kind = 3
		for i := 0; i < 3; i++ {
			n, err := colorNumber(m[i+1])
			if err != nil {
				return Color{}, fmt.Errorf("invalid format")
			}
			c.rgb[i] = n
		}
		return c, nil
	}
	if colorNumberPattern.MatchString(s) {
		if n, err := colorNumber(s); err == nil {
			return Color{kind: 2, n: n}, nil
		}
	}
	return Color{}, fmt.Errorf("invalid format")
}

var attributeNames = []string{"bold", "faint", "italic", "underline", "blinkSlow", "blinkRapid", "inverse", "conceal", "crossOut", "frame", "encircle", "overline"}
var attributeCodes = []int{1, 2, 3, 4, 5, 6, 7, 8, 9, 51, 52, 53}

type Style struct {
	Hide       bool
	Foreground Color
	Background Color
	Attributes [12]bool
}

func (s Style) open() string {
	var out strings.Builder
	out.WriteString(s.Background.escape(true))
	out.WriteString(s.Foreground.escape(false))
	for i, enabled := range s.Attributes {
		if enabled {
			fmt.Fprintf(&out, "\x1b[%dm", attributeCodes[i])
		}
	}
	return out.String()
}

func (s Style) wrap(text string) string {
	if s.Hide {
		return ""
	}
	if prefix := s.open(); prefix != "" {
		return prefix + text + "\x1b[0m"
	}
	return text
}

func namedStyle(name string, bold bool, hide bool) Style {
	c, _ := parseColor(name)
	s := Style{Foreground: c, Hide: hide}
	s.Attributes[0] = bold
	return s
}
