cat > editor.go <<'EOF'
package main

import (
	"io"
	"regexp"
	"strconv"
	"strings"
)

// All expressions operate on a complete line, including its terminating LF.
// Some package fields intentionally admit a newline, unlike a whitespace class.
var (
	buildLine = regexp.MustCompile(`(?m)^# ([^ ]+)( \[[^ ]+\])?$`)
	startLine = regexp.MustCompile(`(?m)^=== RUN   Test.*$`)
	passLine  = regexp.MustCompile(`(?m)^[ \t]*--- PASS: Test.*$`)
	failLine  = regexp.MustCompile(`(?m)^[ \t]*--- FAIL: Test.*$`)
	skipLine  = regexp.MustCompile(`(?m)^[ \t]*--- SKIP: Test.*$`)
	passPkg   = regexp.MustCompile(`(?m)^PASS[ \t]*$`)
	failPkg   = regexp.MustCompile(`(?m)^FAIL[ \t]*$`)
	okSummary = regexp.MustCompile(`(?m)^ok[ \t]+([^ \t]+)[ \t]*(?:[0-9.]+\w+|\(cached\))?[ \t]*(coverage: [0-9]+\.[0-9]% of statements)?(?:[ \t]*\[no tests to run\])?$`)
	badSummary = regexp.MustCompile(`(?m)^FAIL([ \t]+[^ \t]+[ \t]+(?:[0-9.]+\w+|\[build failed\]))$`)
	noTests = regexp.MustCompile(`(?m)^\?[ \t]+([^ \t]+[ \t]+\[(?:no test files|no tests to run)\])$`)
	coverageLine = regexp.MustCompile(`(?m)^coverage: ([0-9]+\.[0-9])% of statements$`)
	fileLocation = regexp.MustCompile(`([^\s:]+\.go)(:[0-9]+(?::[0-9]+)?)`)
)

type Editor struct {
	config   Config
	current  Style
	removals []*regexp.Regexp
}

func newEditor(config Config) *Editor {
	e := &Editor{config: config}
	for _, removal := range config.Removals {
		e.removals = append(e.removals, regexp.MustCompile(removal))
	}
	return e
}

func (e *Editor) label(kind string) string {
	if e.config.LabelType == "long" {
		switch kind {
		case "build": return "BUILD| "
		case "start": return "START| "
		case "pass": return "PASS | "
		case "fail": return "FAIL | "
		case "skip": return "SKIP | "
		case "cover": return "COVER| "
		default: return "     | "
		}
	}
	if e.config.LabelType == "short" {
		switch kind {
		case "build": return "!! "
		case "start": return ">  "
		case "pass": return "o  "
		case "fail": return "x  "
		case "skip": return "-  "
		case "cover": return "%  "
		default: return "   "
		}
	}
	return ""
}

func (e *Editor) files(text string, restore Style) string {
	return fileLocation.ReplaceAllStringFunc(text, func(s string) string {
		m := fileLocation.FindStringSubmatch(s)
		return e.config.Styles["fileStyle"].wrap(m[1]) +
			e.config.Styles["lineStyle"].wrap(m[2]) + restore.open()
	})
}

func (e *Editor) edit(line string) string {
	oldStyle := e.current
	text := line
	special := false
	// Replacing a match rather than stripping the final LF preserves the
	// package-summary grammar's behavior for missing optional fields.
	replace := func(pattern *regexp.Regexp, kind string, style Style, fn func([]string) string) bool {
		loc := pattern.FindStringSubmatchIndex(text)
		if loc == nil { return false }
		m := pattern.FindStringSubmatch(text)
		body := e.label(kind) + fn(m)
		body = e.files(body, oldStyle)
		text = text[:loc[0]] + style.wrap(body) + text[loc[1]:]
		special = true
		return true
	}
	testName := func(prefix string, m []string) string {
		s := strings.TrimLeft(m[0], " ")
		if !e.config.LeaveTestPrefix { prefix += "Test" }
		s = strings.TrimPrefix(s, prefix)
		return strings.Repeat("  ", strings.Count(s, "/")) + s
	}

	switch {
	case replace(buildLine, "build", e.config.Styles["buildStyle"], func(m []string) string { return m[1] + m[2] }):
		e.current = e.config.Styles["buildStyle"]
	case replace(startLine, "start", e.config.Styles["startStyle"], func(m []string) string { return testName("=== RUN   ", m) }):
		e.current = e.config.Styles["startStyle"]
		e.current.Hide = false
	case replace(passLine, "pass", e.config.Styles["passStyle"], func(m []string) string { return testName("--- PASS: ", m) }):
		e.current = e.config.Styles["passStyle"]
	case replace(failLine, "fail", e.config.Styles["failStyle"], func(m []string) string { return testName("--- FAIL: ", m) }):
		e.current = e.config.Styles["failStyle"]
	case replace(skipLine, "skip", e.config.Styles["skipStyle"], func(m []string) string { return testName("--- SKIP: ", m) }):
		e.current = e.config.Styles["skipStyle"]
	case passPkg.MatchString(text):
		text = passPkg.ReplaceAllStringFunc(text, func(string) string { return e.config.Styles["passPackageStyle"].wrap("PASS") })
		special = true
	case failPkg.MatchString(text):
		text = failPkg.ReplaceAllStringFunc(text, func(string) string { return e.config.Styles["failPackageStyle"].wrap("FAIL") })
		special = true
	case replace(okSummary, "pass", e.config.Styles["passStyle"], func(m []string) string { return m[1] + " " + m[2] }):
		e.current = e.config.Styles["passStyle"]
	case replace(badSummary, "fail", e.config.Styles["failStyle"], func(m []string) string { return m[1] }):
		e.current = e.config.Styles["failStyle"]
	case replace(noTests, "skip", e.config.Styles["skipStyle"], func(m []string) string { return m[1] }):
		e.current = e.config.Styles["skipStyle"]
	case coverageLine.MatchString(text):
		m := coverageLine.FindStringSubmatch(text)
		n, _ := strconv.ParseFloat(m[1], 64)
		style := e.config.Styles["coveredStyle"]
		if n < float64(e.config.CoverThreshold) { style = e.config.Styles["uncoveredStyle"] }
		replace(coverageLine, "cover", style, func(m []string) string {
			filled := int(n) / 10
			return m[1] + "% [" + strings.Repeat("#", filled) + strings.Repeat("_", 10-filled) + "]"
		})
	}
	if !special { text = e.files(text, oldStyle) }
	for _, r := range e.removals { text = r.ReplaceAllString(text, "") }
	if text == "" || text == "\n" { return "" }
	if !special {
		newline := ""
		if strings.HasSuffix(text, "\n") {
			text = strings.TrimSuffix(text, "\n")
			newline = "\n"
		}
		if e.current.Hide { return "" }
		text = e.current.wrap(e.label("") + text) + newline
	}
	return text
}

// lineWriter is a streaming filter. A successful command flushes its final
// partial line; an unsuccessful command leaves that partial line unprinted.
type lineWriter struct {
	destination io.Writer
	editor      *Editor
	pending     string
}

func (w *lineWriter) emit(line string) error {
	line = strings.TrimSuffix(line, "\r") + "\n"
	if w.editor != nil { line = w.editor.edit(line) }
	_, err := io.WriteString(w.destination, line)
	return err
}

func (w *lineWriter) Write(b []byte) (int, error) {
	w.pending += string(b)
	for {
		n := strings.IndexByte(w.pending, '\n')
		if n < 0 { break }
		line := w.pending[:n]
		w.pending = w.pending[n+1:]
		if err := w.emit(line); err != nil { return 0, err }
	}
	return len(b), nil
}

func (w *lineWriter) Close() error {
	err := w.emit(w.pending)
	w.pending = ""
	return err
}
EOF"}

