cat > config.go <<'EOF'
package main

import (
	"fmt"
	"go/build"
	"log"
	"os"
	"path/filepath"
	"strings"
)

type Config struct {
	LabelType       string
	Styles          map[string]Style
	CoverThreshold  int
	Removals        []string
	LeaveTestPrefix bool
}

func defaultConfig() Config {
	return Config{
		LabelType: "long", CoverThreshold: 50,
		Styles: map[string]Style{
			"buildStyle": namedStyle("yellow", true, false),
			"startStyle": namedStyle("lightBlack", false, false),
			"passStyle": namedStyle("green", false, false),
			"failStyle": namedStyle("red", true, false),
			"skipStyle": namedStyle("lightBlack", false, false),
			"passPackageStyle": namedStyle("green", false, true),
			"failPackageStyle": namedStyle("red", true, true),
			"coveredStyle": namedStyle("green", false, false),
			"uncoveredStyle": namedStyle("yellow", true, false),
			"fileStyle": namedStyle("cyan", false, false),
			"lineStyle": namedStyle("magenta", false, false),
		},
	}
}
func (c Config) clone() Config {
	copy:=c
	copy.Styles=make(map[string]Style,len(c.Styles))
	for k,v:=range c.Styles {copy.Styles[k]=v}
	copy.Removals=append([]string(nil),c.Removals...)
	return copy
}

func decodeConfig(c Config, node *yamlNode) (Config,error) {
	if node.kind=="null" {return c,nil}
	if node.kind!="map" {return c,fmt.Errorf("yaml: unmarshal errors:\n%s",yamlTypeError(node,"config.Config"))}
	var errors []string
	for _,p:=range yamlPairs(node) {
		n:=p.value
		if n.kind=="null" {if p.key=="removals" {c.Removals=nil};continue}
		switch p.key {
		case "labelType":
			if n.kind=="map" || n.kind=="seq" {errors=append(errors,yamlTypeError(n,"string"))} else {c.LabelType=n.text}
		case "coverThreshold":
			if v,ok:=yamlInt(n);ok {c.CoverThreshold=v} else {errors=append(errors,yamlTypeError(n,"int"))}
		case "leaveTestPrefix":
			if n.kind=="bool" {c.LeaveTestPrefix=yamlBool(n)} else {errors=append(errors,yamlTypeError(n,"bool"))}
		case "removals":
			if n.kind!="seq" {errors=append(errors,yamlTypeError(n,"[]string"));continue}
			c.Removals=nil
			for _,v:=range n.items {
				if v.kind=="map" || v.kind=="seq" {errors=append(errors,yamlTypeError(v,"string"))} else if v.kind!="null" {c.Removals=append(c.Removals,v.text)}
			}
		default:
			s,known:=c.Styles[p.key];if !known {continue}
			if n.kind!="map" {errors=append(errors,yamlTypeError(n,"config.Style"));continue}
			for _,field:=range yamlPairs(n) {
				v:=field.value
				if v.kind=="null" {continue}
				if field.key=="foreground" || field.key=="background" {
					if v.kind=="map" || v.kind=="seq" {errors=append(errors,yamlTypeError(v,"string"));continue}
					color,err:=parseColor(v.text);if err!=nil{return c,err}
					if field.key=="foreground"{s.Foreground=color}else{s.Background=color}
					continue
				}
				index:=-1
				for i,name:=range attributeNames {if name==field.key {index=i;break}}
				if index<0 && field.key!="hide" {continue}
				if v.kind!="bool" {errors=append(errors,yamlTypeError(v,"bool"));continue}
				if field.key=="hide" {s.Hide=yamlBool(v)}else{s.Attributes[index]=yamlBool(v)}
			}
			c.Styles[p.key]=s
		}
	}
	if len(errors)>0 {return c,fmt.Errorf("yaml: unmarshal errors:\n%s",strings.Join(errors,"\n"))}
	return c,nil
}

func loadConfig() Config {
	config:=defaultConfig()
	cwd,err:=os.Getwd()
	if err!=nil {cwd=""}
	dirs:=[]string{cwd}
	if os.Getenv("RICHGO_LOCAL")!="1" {
		dirs=append(dirs,filepath.SplitList(build.Default.GOPATH)...)
		dirs=append(dirs,build.Default.GOROOT,os.Getenv("HOME"))
	}
	for _,dir:=range dirs {
		for _,suffix:=range []string{"", ".yaml", ".yml"} {
			path:=filepath.Join(dir,".richstyle"+suffix)
			data,err:=os.ReadFile(path)
			if err!=nil {
				if !os.IsNotExist(err) {log.Printf("error reading from %s :  %v",path,err)}
				continue
			}
			node,err:=parseYAML(string(data))
			next:=config.clone()
			if err==nil {next,err=decodeConfig(next,node)}
			if err!=nil {log.Printf("error unmarshaling yaml from %s :  %v",path,err);continue}
			config=next
		}
	}
	return config
}
