package main

// This small YAML reader is self-contained. It handles block and flow
// collections, quoted scalars, aliases, and the scalar types used by styles.

import (
	"fmt"
	"math"
	"strconv"
	"strings"
	"unicode/utf8"
)

type yamlPair struct { key string; value *yamlNode }
type yamlNode struct {
	kind string
	text string
	line int
	pairs []yamlPair
	items []*yamlNode
}
type yamlLine struct { text string; indent, number int }
type yamlReader struct {
	lines []yamlLine
	pos int
	anchors map[string]*yamlNode
}

func yamlError(line int, message string) error {
	if line < 1 { line = 1 }
	return fmt.Errorf("yaml: line %d: %s", line, message)
}

func stripYAMLComment(s string) string {
	var quote byte
	for i := 0; i < len(s); i++ {
		c := s[i]
		if quote == '"' && c == '\\' { i++; continue }
		if quote != 0 {
			if c == quote {
				if quote == '\'' && i+1 < len(s) && s[i+1] == '\'' { i++; continue }
				quote = 0
			}
			continue
		}
		if (c == '"' || c == '\'') && (i == 0 || strings.ContainsRune(" \t:,[{", rune(s[i-1]))) { quote = c; continue }
		if c == '#' && (i == 0 || s[i-1] == ' ' || s[i-1] == '\t') { return strings.TrimRight(s[:i], " \t") }
	}
	return strings.TrimRight(s, " \t")
}

func parseYAML(data string) (*yamlNode, error) {
	if !utf8.ValidString(data) { return nil, fmt.Errorf("yaml: invalid leading UTF-8 octet") }
	data = strings.TrimPrefix(data, "\ufeff")
	r := &yamlReader{anchors: make(map[string]*yamlNode)}
	for i, raw := range strings.Split(data, "\n") {
		raw = strings.TrimSuffix(raw, "\r")
		for _, c := range raw {
			if c < 32 && c != '\t' { return nil, fmt.Errorf("yaml: control characters are not allowed") }
		}
		n := len(raw)-len(strings.TrimLeft(raw, " "))
		if len(raw)>n && raw[n]=='\t' { return nil, yamlError(i+1, "found character that cannot start any token") }
		s := stripYAMLComment(raw[n:])
		if strings.TrimSpace(s)=="" { continue }
		if n == 0 && (s == "---" || s == "...") {
			if len(r.lines)>0 { break }
			if s == "..." { break }
			continue
		}
		if n == 0 && strings.HasPrefix(s, "%YAML") { continue }
		r.lines = append(r.lines, yamlLine{s, n, i+1})
	}
	if len(r.lines)==0 { return &yamlNode{kind:"null", line:1}, nil }
	n, err := r.block(r.lines[0].indent)
	if err != nil { return nil, err }
	if r.pos < len(r.lines) { return nil, yamlError(r.lines[r.pos].number, "did not find expected key") }
	return n, nil
}

func yamlColon(s string) int {
	var quote byte
	depth := 0
	for i:=0;i<len(s);i++ {
		c:=s[i]
		if quote=='"' && c=='\\' {i++;continue}
		if quote!=0 {
			if c==quote {
				if quote=='\'' && i+1<len(s) && s[i+1]=='\'' {i++;continue}
				quote=0
			}
			continue
		}
		if c=='\'' || c=='"' { quote=c;continue }
		if c=='[' || c=='{' {depth++}
		if c==']' || c=='}' {depth--}
		if c==':' && depth==0 && (i+1==len(s) || s[i+1]==' ' || s[i+1]=='\t') { return i }
	}
	return -1
}
func yamlSequence(s string) bool { return s=="-" || strings.HasPrefix(s,"- ") || strings.HasPrefix(s,"-\t") }

func (r *yamlReader) block(indent int) (*yamlNode,error) {
	if r.pos>=len(r.lines) { return &yamlNode{kind:"null", line:1}, nil }
	start:=r.lines[r.pos]
	if yamlSequence(start.text) {
		n:=&yamlNode{kind:"seq",line:start.number}
		for r.pos<len(r.lines) {
			l:=r.lines[r.pos]
			if l.indent!=indent || !yamlSequence(l.text) {break}
			r.pos++
			v,err:=r.value(strings.TrimSpace(l.text[1:]),l.number,indent)
			if err!=nil{return nil,err}
			n.items=append(n.items,v)
		}
		return n,nil
	}
	if yamlColon(start.text)<0 {
		r.pos++
		return r.value(start.text,start.number,indent)
	}
	n:=&yamlNode{kind:"map",line:start.number}
	for r.pos<len(r.lines) {
		l:=r.lines[r.pos]
		if l.indent<indent {break}
		if l.indent>indent {return nil,yamlError(l.number,"did not find expected key")}
		colon:=yamlColon(l.text)
		if colon<0 {
			if yamlSequence(l.text) { break }
			return nil,yamlError(l.number,"could not find expected ':'")
		}
		keyText:=strings.TrimSpace(l.text[:colon])
		key,err:=r.inline(keyText,l.number)
		if err!=nil{return nil,err}
		if key.kind=="map" || key.kind=="seq" { return nil,fmt.Errorf("yaml: invalid map key: interface {}") }
		r.pos++
		v,err:=r.value(strings.TrimSpace(l.text[colon+1:]),l.number,indent)
		if err!=nil{return nil,err}
		n.pairs=append(n.pairs,yamlPair{key.text,v})
	}
	return n,nil
}

func takeYAMLToken(s string) (string,string) {
	i:=strings.IndexAny(s," \t\n,]}")
	if i<0 {return s,""}
	return s[:i],strings.TrimLeft(s[i:]," \t")
}

func (r *yamlReader) value(s string, line, parentIndent int) (*yamlNode,error) {
	anchor:=""
	if strings.HasPrefix(s,"&") {
		var rest string
		anchor,rest=takeYAMLToken(s[1:]);s=rest
	}
	var n *yamlNode
	var err error
	if s=="" {
		if r.pos<len(r.lines) && (r.lines[r.pos].indent>parentIndent || (r.lines[r.pos].indent==parentIndent && yamlSequence(r.lines[r.pos].text))) {
			n,err=r.block(r.lines[r.pos].indent)
		} else {n=&yamlNode{kind:"null",line:line}}
	} else if s[0]=='|' || s[0]=='>' {
		var parts []string
		for r.pos<len(r.lines) && r.lines[r.pos].indent>parentIndent {
			parts=append(parts,r.lines[r.pos].text);r.pos++
		}
		join:="\n";if s[0]=='>' {join=" "}
		str:=strings.Join(parts,join)
		if !strings.Contains(s,"-") && len(parts)>0 {str+="\n"}
		n=&yamlNode{kind:"str",text:str,line:line}
	} else {
		// A flow collection or a quoted scalar can span physical lines.
		if s[0]=='[' || s[0]=='{' || s[0]=='"' || s[0]=='\'' {
			for yamlUnclosed(s) && r.pos<len(r.lines) {
				s+="\n"+r.lines[r.pos].text;r.pos++
			}
		}
		n,err=r.inline(s,line)
		if err==nil && n.kind=="str" && len(s)>0 && !strings.ContainsAny(s[:1],"[{'\"*!") {
			for r.pos<len(r.lines) && r.lines[r.pos].indent>parentIndent && yamlColon(r.lines[r.pos].text)<0 && !yamlSequence(r.lines[r.pos].text) {
				n.text+=" "+r.lines[r.pos].text;r.pos++
			}
		}
	}
	if err==nil && anchor!="" {r.anchors[anchor]=n}
	return n,err
}

func yamlUnclosed(s string) bool {
	var quote byte
	depth:=0
	for i:=0;i<len(s);i++ {
		c:=s[i]
		if quote=='"' && c=='\\' {i++;continue}
		if quote!=0 {
			if c==quote {
				if quote=='\'' && i+1<len(s) && s[i+1]=='\'' {i++;continue}
				quote=0
			}
			continue
		}
		if c=='\'' || c=='"' {quote=c;continue}
		if c=='[' || c=='{' {depth++}
		if c==']' || c=='}' {depth--}
	}
	return quote!=0 || depth>0
}

type yamlFlow struct { reader *yamlReader; s string; pos,line int }
func (f *yamlFlow) skip() {
	for f.pos<len(f.s) && strings.ContainsRune(" \t\n\r",rune(f.s[f.pos])) {
		if f.s[f.pos]=='\n' {f.line++};f.pos++
	}
}
func (r *yamlReader) inline(s string,line int) (*yamlNode,error) {
	f:=&yamlFlow{reader:r,s:s,line:line}
	n,err:=f.node(false)
	if err!=nil{return nil,err}
	f.skip()
	if f.pos<len(s) {return nil,yamlError(f.line,"did not find expected key")}
	return n,nil
}
func (f *yamlFlow) node(flow bool) (*yamlNode,error) {
	f.skip();line:=f.line
	if f.pos>=len(f.s) {return &yamlNode{kind:"null",line:line},nil}
	c:=f.s[f.pos]
	if c=='&' {
		f.pos++;start:=f.pos
		for f.pos<len(f.s) && !strings.ContainsRune(" \t\n,]}",rune(f.s[f.pos])) {f.pos++}
		name:=f.s[start:f.pos];n,err:=f.node(flow)
		if err==nil{f.reader.anchors[name]=n};return n,err
	}
	if c=='*' {
		f.pos++;start:=f.pos
		for f.pos<len(f.s) && !strings.ContainsRune(" \t\n,]}",rune(f.s[f.pos])) {f.pos++}
		name:=f.s[start:f.pos]
		n,ok:=f.reader.anchors[name]
		if !ok{return nil,fmt.Errorf("yaml: unknown anchor '%s' referenced",name)}
		return n,nil
	}
	if c=='!' {
		start:=f.pos
		for f.pos<len(f.s) && !strings.ContainsRune(" \t\n",rune(f.s[f.pos])) {f.pos++}
		tag:=f.s[start:f.pos]
		n,err:=f.node(flow)
		if err!=nil{return nil,err}
		copy:=*n;n=&copy
