	}
	if c=='[' {
		f.pos++;n:=&yamlNode{kind:"seq",line:line}
		for {
			f.skip()
			if f.pos>=len(f.s){return nil,yamlError(line,"did not find expected node content")}
			if f.s[f.pos]==']'{f.pos++;return n,nil}
			v,err:=f.node(true);if err!=nil{return nil,err};n.items=append(n.items,v)
			f.skip()
			if f.pos>=len(f.s){return nil,yamlError(line,"did not find expected ',' or ']'")}
			if f.s[f.pos]==']'{f.pos++;return n,nil}
			if f.s[f.pos]!=','{return nil,yamlError(f.line,"did not find expected ',' or ']'")}
			f.pos++
		}
	}
	if c=='{' {
		f.pos++;n:=&yamlNode{kind:"map",line:line}
		for {
			f.skip()
			if f.pos>=len(f.s){return nil,yamlError(line,"did not find expected node content")}
			if f.s[f.pos]=='}'{f.pos++;return n,nil}
