			f.skip()
			if f.pos>=len(f.s){return nil,yamlError(line,"did not find expected ',' or '}'")}
			if f.s[f.pos]=='}'{f.pos++;return n,nil}
			if f.s[f.pos]!=','{return nil,yamlError(f.line,"did not find expected ',' or '}'")}
			f.pos++
		}
	}
	if c=='\'' || c=='"' {
		s,err:=f.quoted();return &yamlNode{kind:"str",text:s,line:line},err
	}
	if c=='@' || c=='`' {return nil,yamlError(line,"found character that cannot start any token")}
	start:=f.pos
	for f.pos<len(f.s) {
		c=f.s[f.pos]
		if flow && strings.ContainsRune(",]}",rune(c)){break}
		f.pos++
	}
	s:=strings.TrimSpace(f.s[start:f.pos])
	if s!="" && yamlColon(s)>=0 {return nil,yamlError(line,"mapping values are not allowed in this context")}
	return yamlScalar(s,line),nil
}
func (f *yamlFlow) key() (string,error) {
	f.skip()
	if f.pos<len(f.s) && (f.s[f.pos]=='\'' || f.s[f.pos]=='"') {return f.quoted()}
	start:=f.pos
	for f.pos<len(f.s) && !strings.ContainsRune(":,}",rune(f.s[f.pos])) {f.pos++}
