	for f.pos<len(f.s) {
		c:=f.s[f.pos];f.pos++
		if c==quote {
			if quote=='\'' && f.pos<len(f.s) && f.s[f.pos]=='\'' {out.WriteByte('\'');f.pos++;continue}
			return out.String(),nil
		}
		if c=='\n' {f.line++;out.WriteByte(' ');continue}
		if quote=='\'' || c!='\\' {out.WriteByte(c);continue}
		if f.pos>=len(f.s){break}
		c=f.s[f.pos];f.pos++
		switch c {
		case '0':out.WriteByte(0)
		case 'a':out.WriteByte('\a')
		case 'b':out.WriteByte('\b')
		case 't','\t':out.WriteByte('\t')
		case 'n':out.WriteByte('\n')
		case 'v':out.WriteByte('\v')
		case 'f':out.WriteByte('\f')
		case 'r':out.WriteByte('\r')
		case 'e':out.WriteByte(27)
		case ' ','"','/','\\':out.WriteByte(c)
		case 'N':out.WriteRune('\u0085')
		case '_':out.WriteRune('\u00a0')
		case 'L':out.WriteRune('\u2028')
		case 'P':out.WriteRune('\u2029')
		case '\n':f.line++;f.skip()
		case 'x','u','U':
			n:=2;if c=='u'{n=4};if c=='U'{n=8}
			if f.pos+n>len(f.s){return "",yamlError(f.line,"did not find expected hexdecimal number")}
			v,err:=strconv.ParseUint(f.s[f.pos:f.pos+n],16,32)
			if err!=nil{return "",yamlError(f.line,"did not find expected hexdecimal number")}
			f.pos+=n
			if v>utf8.MaxRune || (v>=0xd800 && v<=0xdfff){return "",yamlError(f.line,"found invalid Unicode character escape code")}
			out.WriteRune(rune(v))
		default:return "",yamlError(f.line,"found unknown escape character")
		}
	}
	return "",yamlError(startLine,"found unexpected end of stream")
}

func yamlScalar(s string,line int) *yamlNode {
	n:=&yamlNode{kind:"str",text:s,line:line}
	switch s {
	case "","~","null","Null","NULL":n.kind="null";return n
	case "y","Y","yes","Yes","YES","n","N","no","No","NO","true","True","TRUE","false","False","FALSE","on","On","ON","off","Off","OFF":n.kind="bool";return n
	}
	x:=strings.ReplaceAll(s,"_","")
	if _,err:=strconv.ParseInt(x,0,64);err==nil{n.kind="int";return n}
	if _,err:=strconv.ParseUint(x,0,64);err==nil{n.kind="int";return n}
	if _,err:=strconv.ParseFloat(x,64);err==nil{n.kind="float";return n}
	switch strings.ToLower(x){case ".nan",".inf","+.inf","-.inf":n.kind="float"}
	return n
}
func yamlBool(n *yamlNode) bool {
	switch strings.ToLower(n.text){case "y","yes","true","on":return true};return false
}
func yamlInt(n *yamlNode) (int,bool) {
	x:=strings.ReplaceAll(n.text,"_","")
	if n.kind=="int" {
		v,err:=strconv.ParseInt(x,0,64);return int(v),err==nil
	}
	if n.kind=="float" {
		v,err:=strconv.ParseFloat(x,64)
		if err==nil && !math.IsNaN(v) && v<=math.MaxInt64 && v>=math.MinInt64 {return int(v),true}
	}
	return 0,false
}

func yamlTypeError(n *yamlNode, dest string) string {
	if n.kind=="map" || n.kind=="seq" {return fmt.Sprintf("  line %d: cannot unmarshal !!%s into %s",n.line,n.kind,dest)}
	s:=n.text
	if len(s)>10 {s=s[:7]+"..."}
	return fmt.Sprintf("  line %d: cannot unmarshal !!%s `%s` into %s",n.line,n.kind,s,dest)
}

// A merge key fills in unspecified entries. Ordinary mapping keys retain
// their YAML order, so repeated entries are decoded in order as well.
func yamlPairs(n *yamlNode) []yamlPair {
	if n==nil || n.kind!="map" {return nil}
	explicit:=make(map[string]bool)
	for _,p:=range n.pairs {if p.key!="<<" {explicit[p.key]=true}}
	seen:=make(map[string]bool)
	var out []yamlPair
	var merge func(*yamlNode)
	merge=func(m *yamlNode) {
		if m.kind=="seq" {for _,v:=range m.items{merge(v)};return}
		for _,p:=range yamlPairs(m) {if !explicit[p.key] && !seen[p.key] {out=append(out,p);seen[p.key]=true}}
	}
	for _,p:=range n.pairs {if p.key=="<<"{merge(p.value)}}
	for _,p:=range n.pairs {if p.key!="<<"{out=append(out,p)}}
	return out
}
