	cmd.Stdout=os.Stdout
	cmd.Stderr=os.Stderr
	var out,errout *lineWriter
	if filter {
		out=&lineWriter{destination:os.Stdout}
		errout=&lineWriter{destination:os.Stderr}
		if os.Getenv("RICHGO_FORCE_COLOR")!="" || terminal(os.Stderr.Fd()) {
