	input := "=== RUN   TestA\r\n    a.go:31: hello\n--- PASS: TestA\nend"
	for _, pretty := range []bool{false, true} {
		want := formatted(t, input, defaultConfig(), pretty)
		for split := 0; split <= len(input); split++ {
			var out bytes.Buffer
			w := &lineWriter{destination: &out}
			if pretty {
				w.editor = newEditor(defaultConfig())
			}
			w.Write([]byte(input[:split]))
