func TestStreamingChunks(t *testing.T) {
	input := "=== RUN   TestA\r\n    a.go:31: hello\n--- PASS: TestA\nend"
	for _, pretty := range []bool{false, true} {
		want := formatted(t, input, defaultConfig(), pretty)
		for split := 0; split <= len(input); split++ {
			var out bytes.Buffer
			w := &lineWriter{destination: &out}
			if pretty {
				w.editor = newEditor(defaultConfig())
			}
			w.Write([]byte(input[:split]))
			w.Write([]byte(input[split:]))
			w.Close()
			if out.String() != want {
				t.Fatalf("chunk boundary %d changes output", split)
			}
		}
	}
	var out bytes.Buffer
	w := &lineWriter{destination: &out}
	w.Write([]byte("complete\nincomplete"))
	if out.String() != "complete\n" {
		t.Fatalf("partial line should be held until Close: %q", out.String())
	}
	if got := formatted(t, strings.Repeat("x", 100000)+"\n", defaultConfig(), true); len(got) != 100008 {
		t.Fatalf("long lines were not preserved: %d bytes", len(got))
	}
}
