	t.Setenv("RICHGO_LOCAL", "1")
	files := map[string]string{
		".richstyle":      "labelType: short\nstartStyle: {foreground: blue, bold: true}\n",
		".richstyle.yaml": "startStyle: {foreground: cyan}\npassPackageStyle: {hide: false}\n",
		".richstyle.yml":  "labelType: none\nstartStyle: {foreground: BAD}\n",
	}
	for name, data := range files {
		if err := os.WriteFile(filepath.Join(dir, name), []byte(data), 0600); err != nil {
			t.Fatal(err)
		}
	}
	var warnings bytes.Buffer
	oldOutput := log.Writer()
	log.SetOutput(&warnings)
	defer log.SetOutput(oldOutput)
	c := loadConfig()
	if c.LabelType != "short" || c.Styles["startStyle"].open() != "\x1b[36m\x1b[1m" || c.Styles["passPackageStyle"].Hide {
